window.__PAGE_RUNTIME_PARTIALS__["partials/guia-04-planificar-ciberseguridad-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA \u0026middot; FPI\u003c/div\u003e\n      \u003ch2\u003eGu\u0026iacute;a 4 - Planificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinform\u0026aacute;ticos\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformaci\u0026oacute;n\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificaci\u0026oacute;n\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentaci\u0026oacute;n\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexi\u0026oacute;n Inicial\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualizaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#materiales\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128230;\u003c/span\u003e Material de apoyo\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eGu\u0026iacute;a asignada\u003c/div\u003e\n      \u003ca class=\"nav-guide current\" id=\"currentGuideNavLink\" href=\"grupo-10a-guia-04-planificar-informacion-ciberseguridad.html\" data-current-file=\"grupo-10a-guia-04-planificar-informacion-ciberseguridad.html\"\u003e\n        \u003cspan class=\"g-icon\"\u003e\u0026#128215;\u003c/span\u003e\n        \u003cspan class=\"g-info\"\u003e\n          \u003cspan class=\"g-num\"\u003eGu\u0026iacute;a 4\u003c/span\u003e\n          \u003cspan class=\"g-name\" id=\"currentGuideNavLabel\"\u003ePlanificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad | 10A\u003c/span\u003e\n        \u003c/span\u003e\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\n        \u003cstrong\u003eGu\u0026iacute;a 4 - Planificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad\u003c/strong\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003e56 horas\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eKennedy | Grado 10\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eGu\u0026iacute;a 4 | Fase: Planeaci\u0026oacute;n\u003c/div\u003e\n        \u003ch1\u003ePlanificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad\u003c/h1\u003e\n        \u003cp\u003e\n          En esta gu\u0026iacute;a explorar\u0026aacute;s uno de los desaf\u0026iacute;os m\u0026aacute;s cr\u0026iacute;ticos del entorno tecnol\u0026oacute;gico\n          actual: la ciberseguridad. Aprender\u0026aacute;s a identificar amenazas y vulnerabilidades, aplicar\n          controles de seguridad basados en normativa vigente (ISO 27001, Ley 1273 de 2009),\n          implementar \u003cem\u003ehardening\u003c/em\u003e en Windows y documentar todo con rigurosidad t\u0026eacute;cnica,\n          al servicio de las MiPymes de la zona de influencia del CIAS Puerto Boyac\u0026aacute;.\n        \u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Competencia: Operar herramientas inform\u0026aacute;ticas y digitales\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; 56 horas\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; C\u0026oacute;digo: 233108 \u0026middot; V1\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qu\u0026eacute; llevas y qu\u0026eacute; te falta?\u003c/h3\u003e\u003cp\u003eSe actualiza solo con tus entregas y respuestas guardadas\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eEsta tabla se marca sola: \u003cstrong\u003eEntregada\u003c/strong\u003e cuando subes la evidencia a Drive y\n            \u003cstrong\u003eGuardada\u003c/strong\u003e cuando guardas tus respuestas. Lo que siga en Pendiente es lo que te falta.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificaci\u0026oacute;n de la Gu\u0026iacute;a\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDatos del Programa de Formaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003eInformaci\u0026oacute;n oficial del programa y la competencia\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table ident-table\"\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eDenominaci\u0026oacute;n del Programa\u003c/td\u003e\u003ctd\u003eT\u0026eacute;cnico en Sistemas Teleinform\u0026aacute;ticos\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eC\u0026oacute;digo del Programa\u003c/td\u003e\u003ctd\u003e233108 \u0026middot; V1\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eAlfabetizaci\u0026oacute;n Digital, Asesor\u0026iacute;a T\u0026eacute;cnica y Ciberseguridad para la Mejora de Actividades Productivas Locales en la zona de influencia del CIAS Puerto Boyac\u0026aacute;.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003ePlaneaci\u0026oacute;n\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003ePlanificar procesos de intervenci\u0026oacute;n en alfabetizaci\u0026oacute;n digital, asesor\u0026iacute;a t\u0026eacute;cnica y ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e220501121 - Operar herramientas inform\u0026aacute;ticas y digitales de acuerdo con protocolos y manuales t\u0026eacute;cnicos.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003eRAP 03 - Planificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDuraci\u0026oacute;n\u003c/td\u003e\u003ctd\u003e56 horas\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eEmpieza por aquí:\u003c/strong\u003e conoce de qué trata la guía y qué vas a lograr. Léela completa antes de comenzar las actividades.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 ¿Cómo trabajar esta guía? Paso a paso\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eLee la teoría\u003c/strong\u003e de las secciones de contextualización antes de resolver las actividades.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eResuelve cada actividad\u003c/strong\u003e en orden. Escribe tus respuestas en los campos de la guía.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eGuarda tus respuestas\u003c/strong\u003e con el botón de cada actividad. Tu avance queda guardado en este navegador.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega las evidencias\u003c/strong\u003e que lo pidan con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e. Quedan en la carpeta de tu ficha.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eRevisa \"Tu control de avance\"\u003c/strong\u003e (arriba): te muestra qué llevas Entregado, Guardado y Pendiente.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e💡 Recuerda\u003c/div\u003e\n        \u003cp\u003eNo tienes que terminar todo de una vez: puedes salir y volver, tu trabajo se guarda solo. Si una actividad\n        ya fue entregada y necesitas corregirla, pídele a tu instructor que la habilite de nuevo.\u003c/p\u003e\u003c/div\u003e\n\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eBienvenida a la Gu\u0026iacute;a\u003c/h3\u003e\n              \u003cp\u003eConoce el contexto, el alcance y las metas de este recorrido formativo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003e\n            Cordial saludo, aprendiz. En esta gu\u0026iacute;a explorar\u0026aacute;s uno de los desaf\u0026iacute;os m\u0026aacute;s cr\u0026iacute;ticos\n            del entorno tecnol\u0026oacute;gico actual: la \u003cstrong\u003eciberseguridad\u003c/strong\u003e. En un contexto donde las\n            MiPymes de Boyac\u0026aacute; son cada vez m\u0026aacute;s dependientes de la tecnolog\u0026iacute;a, la protecci\u0026oacute;n de su\n            informaci\u0026oacute;n se convierte en una necesidad estrat\u0026eacute;gica y no \u0026uacute;nicamente t\u0026eacute;cnica.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            A trav\u0026eacute;s de las actividades propuestas aprender\u0026aacute;s a: identificar amenazas y\n            vulnerabilidades en sistemas inform\u0026aacute;ticos, aplicar controles de seguridad basados en\n            normativa vigente (ISO 27001, Ley 1273 de 2009), implementar estrategias de\n            \u003cem\u003ehardening\u003c/em\u003e en sistemas operativos Windows, y documentar todos estos procesos con\n            rigurosidad t\u0026eacute;cnica y profesional.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            La gu\u0026iacute;a se centra en el RAP 03: planificar la seguridad de la informaci\u0026oacute;n con criterios\n            t\u0026eacute;cnicos y normativos. A partir del diagn\u0026oacute;stico de seguridad, la implementaci\u0026oacute;n de\n            controles, la elaboraci\u0026oacute;n de pol\u0026iacute;ticas y la gesti\u0026oacute;n de copias de seguridad,\n            desarrollar\u0026aacute;s competencias directamente aplicables en el soporte t\u0026eacute;cnico a las MiPymes\n            de la zona de influencia del CIAS Puerto Boyac\u0026aacute;.\n          \u003c/p\u003e\n          \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Lo que necesitas para esta gu\u0026iacute;a\u003c/div\u003e\n            \u003cp\u003e\n              Equipo con Windows 10/11 (o m\u0026aacute;quina virtual), conexi\u0026oacute;n a internet y las herramientas\n              de diagn\u0026oacute;stico indicadas por el instructor (la mayor\u0026iacute;a son gratuitas). Guarda tus\n              evidencias con nombres descriptivos. \u003cstrong\u003eLas capturas de pantalla son tu respaldo:\n              sin evidencia, no hay evaluaci\u0026oacute;n.\u003c/strong\u003e\n            \u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.1 REFLEXIÓN INICIAL ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 \u0026middot; Actividades de Reflexi\u0026oacute;n Inicial\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de reflexión inicial:\u003c/strong\u003e activa lo que ya sabes sobre el tema. Aquí no se evalúa el acierto, sino tu participación: responde con confianza, no hay respuestas malas.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eExplorar lo que ya sabes o intuyes sobre ciberseguridad a partir de un caso real.\n        No es necesario buscar informaci\u0026oacute;n: escribe lo que sabes, intuyes o piensas. Todo el\n        tiempo de reflexi\u0026oacute;n es trabajo directo con el instructor.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-reflexion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128172;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Reflexi\u0026oacute;n Inicial\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 4 horas directas\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.1.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eAn\u0026aacute;lisis del caso ElectroBoyc\u0026aacute; S.A.S.\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e reflexionar individualmente sobre un caso real de ataque inform\u0026aacute;tico a una empresa peque\u0026ntilde;a. Paso 1 de la reflexi\u0026oacute;n (2 horas).\u003c/p\u003e\n\n              \u003carticle class=\"story-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso \u0026mdash; \u0026laquo;ElectroBoyc\u0026aacute; S.A.S. bajo ataque de ransomware\u0026raquo;\u003c/h3\u003e\n                \u003cp\u003eElectroBoyc\u0026aacute; S.A.S. es una distribuidora de materiales el\u0026eacute;ctricos en Tunja con\n                12 empleados. Un lunes llegaron a trabajar y encontraron todos los archivos cifrados\n                \u0026mdash;facturas, contratos, base de datos de clientes\u0026mdash; con un mensaje exigiendo\n                \u003cstrong\u003eUSD 2.500 en criptomonedas\u003c/strong\u003e.\u003c/p\u003e\n                \u003cp\u003eEl antivirus estaba vencido, no hab\u0026iacute;a copias de seguridad actualizadas y ning\u0026uacute;n\n                empleado ten\u0026iacute;a formaci\u0026oacute;n en ciberseguridad. La empresa cerr\u0026oacute; operaciones durante\n                \u003cstrong\u003e3 semanas\u003c/strong\u003e.\u003c/p\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px;\"\u003e\n                \u003ch3\u003eReflexi\u0026oacute;n individual escrita\u003c/h3\u003e\n                \u003cp class=\"intro-text\" style=\"margin-top:0;font-size:.9rem\"\u003e\n                  Responde con tus propias palabras. No hay respuestas correctas ni incorrectas:\n                  el objetivo es explorar lo que ya sabes o intuyes sobre ciberseguridad.\n                \u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. \u0026iquest;Hab\u0026iacute;as escuchado antes sobre ataques como el que sufri\u0026oacute; ElectroBoyc\u0026aacute;? \u0026iquest;Qu\u0026eacute; sabes sobre ellos?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_311_pregunta1\" data-track placeholder=\"Escribe lo que sabes o has o\u0026iacute;do sobre ransomware, virus o ataques inform\u0026aacute;ticos: noticias, casos cercanos, videos...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. \u0026iquest;Por qu\u0026eacute; crees que una empresa peque\u0026ntilde;a puede ser v\u0026iacute;ctima de un ciberataque si no es famosa ni grande?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_311_pregunta2\" data-track placeholder=\"Piensa: \u0026iquest;qu\u0026eacute; buscan los atacantes? \u0026iquest;Qu\u0026eacute; tan protegida est\u0026aacute; una empresa peque\u0026ntilde;a comparada con un banco?\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Si fueras el t\u0026eacute;cnico de sistemas de ElectroBoyc\u0026aacute;, \u0026iquest;qu\u0026eacute; habr\u0026iacute;as recomendado ANTES del ataque?\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g4c_311_pregunta3\" data-track placeholder=\"Lista medidas concretas: antivirus vigente, copias de seguridad, capacitaci\u0026oacute;n del personal, contrase\u0026ntilde;as...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. \u0026iquest;Qu\u0026eacute; informaci\u0026oacute;n de una empresa consideras m\u0026aacute;s valiosa y por qu\u0026eacute; deber\u0026iacute;a protegerse?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_311_pregunta4\" data-track placeholder=\"Ej.: facturas, contratos, datos de clientes, cuentas bancarias... explica por qu\u0026eacute; su p\u0026eacute;rdida hace tanto da\u0026ntilde;o.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. \u0026iquest;Has protegido alguna vez tu informaci\u0026oacute;n personal en un dispositivo? \u0026iquest;Qu\u0026eacute; hiciste? \u0026iquest;Fue suficiente?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_311_pregunta5\" data-track placeholder=\"Ej.: contrase\u0026ntilde;a o huella en el celular, copia de fotos, verificaci\u0026oacute;n en dos pasos... \u0026iquest;crees que basta?\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"caso311DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarCaso311\" class=\"btn-save-response\" onclick=\"actStd_save_caso311()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_caso311()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusCaso311\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.1.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eSocializaci\u0026oacute;n guiada en plenaria\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e compartir tus ideas con el grupo y escuchar las de tus compa\u0026ntilde;eros. Paso 2 de la reflexi\u0026oacute;n (2 horas).\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003e\u0026iquest;C\u0026oacute;mo funciona la plenaria?\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eEl instructor moderar\u0026aacute; una conversaci\u0026oacute;n abierta con el grupo. No se trata de exponer ni sustentar: comparte tus ideas y escucha las de tus compa\u0026ntilde;eros.\u003c/li\u003e\n                  \u003cli\u003eCada aprendiz comparte brevemente (2-3 minutos) una respuesta de la actividad 3.1.1 que considere interesante o que le haya generado duda.\u003c/li\u003e\n                  \u003cli\u003eEl instructor registra en el tablero las ideas clave que surjan del grupo.\u003c/li\u003e\n                  \u003cli\u003eEl objetivo es identificar qu\u0026eacute; sabe el grupo, qu\u0026eacute; dudas existen y qu\u0026eacute; expectativas tienen sobre la gu\u0026iacute;a.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px;\"\u003e\n                \u003ch3\u003eBit\u0026aacute;cora de la plenaria\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. \u0026iquest;Qu\u0026eacute; respuesta tuya compartiste (o compartir\u0026iacute;as) con el grupo y por qu\u0026eacute; la elegiste?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_312_compartida\" data-track placeholder=\"Escribe la idea que llevaste a la plenaria y qu\u0026eacute; te llam\u0026oacute; la atenci\u0026oacute;n de ella.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. \u0026iquest;Qu\u0026eacute; idea de un compa\u0026ntilde;ero te aport\u0026oacute; algo nuevo o te hizo cambiar de opini\u0026oacute;n?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_312_aporte\" data-track placeholder=\"Anota la idea, qui\u0026eacute;n la comparti\u0026oacute; (opcional) y qu\u0026eacute; te ense\u0026ntilde;\u0026oacute;.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Ideas clave que el instructor registr\u0026oacute; en el tablero (las que m\u0026aacute;s te sirvieron)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_312_tablero\" data-track placeholder=\"Lista 3 o m\u0026aacute;s ideas clave del grupo: dudas comunes, conceptos nuevos, expectativas de la gu\u0026iacute;a.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. S\u0026iacute;ntesis personal (m\u0026iacute;nimo 5 l\u0026iacute;neas): \u0026iquest;qu\u0026eacute; cambi\u0026oacute; en tu comprensi\u0026oacute;n del caso despu\u0026eacute;s de la plenaria?\u003c/span\u003e\n                  \u003ctextarea rows=\"6\" data-store=\"g4c_312_sintesis\" data-track placeholder=\"Escribe qu\u0026eacute; aprendiste al escuchar al grupo y qu\u0026eacute; esperas aprender en esta gu\u0026iacute;a.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"plenaria312DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlenaria312\" class=\"btn-save-response\" onclick=\"actStd_save_plenaria312()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plenaria312()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlenaria312\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.2 CONTEXTUALIZACIÓN ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 \u0026middot; Contextualizaci\u0026oacute;n e Identificaci\u0026oacute;n de Conocimientos\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de contextualización:\u003c/strong\u003e aquí están los conceptos y la teoría que necesitas. Estúdialos con calma — son la base para resolver bien las actividades que siguen.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eEstudiar los bloques tem\u0026aacute;ticos A y B y construir un mapa conceptual integrador al\n        finalizar. Esta base conceptual es la que usar\u0026aacute;s en el diagn\u0026oacute;stico, el \u003cem\u003ehardening\u003c/em\u003e\n        y el Plan de Ciberseguridad.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-contexto\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128269;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Contextualizaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Estudio de bloques tem\u0026aacute;ticos + mapa conceptual integrador\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.2.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEstudio de los bloques tem\u0026aacute;ticos A y B\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n diagn\u0026oacute;stica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e estudiar los contenidos de ciberseguridad (Bloque A) y de documentaci\u0026oacute;n t\u0026eacute;cnica (Bloque B) que sustentan toda la gu\u0026iacute;a.\u003c/p\u003e\n\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:16px\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:30%\"\u003eTema (Bloque A)\u003c/th\u003e\n                      \u003cth\u003eContenidos a estudiar\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eFundamentos de ciberseguridad\u003c/td\u003e\u003ctd\u003eConceptos esenciales: amenaza, vulnerabilidad, riesgo, activo de informaci\u0026oacute;n, incidente. Triada CIA: Confidencialidad, Integridad, Disponibilidad. Diferencia entre seguridad inform\u0026aacute;tica y ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eTipos de ciberataques\u003c/td\u003e\u003ctd\u003eMalware (virus, troyanos, ransomware, spyware). Ataques de red (phishing, man-in-the-middle, DoS/DDoS). Ingenier\u0026iacute;a social. Casos reales en Colombia (CSIRT, INCIBE).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eNormativa y marco legal\u003c/td\u003e\u003ctd\u003eISO/IEC 27001: SGSI. Ley 1273 de 2009: delitos inform\u0026aacute;ticos en Colombia. CONPES 3995: Pol\u0026iacute;tica Nacional de Confianza y Seguridad Digital. Lineamientos MinTIC para MiPymes.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eControles de seguridad\u003c/td\u003e\u003ctd\u003eTipos: preventivos, detectivos y correctivos. NIST Cybersecurity Framework: Identificar, Proteger, Detectar, Responder, Recuperar. Controles t\u0026eacute;cnicos b\u0026aacute;sicos para MiPymes.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eHardening de Windows\u003c/td\u003e\u003ctd\u003eWindows Defender: protecci\u0026oacute;n en tiempo real + an\u0026aacute;lisis programado. Firewall: reglas de entrada y salida. SmartScreen y control de aplicaciones. Pol\u0026iacute;ticas de contrase\u0026ntilde;as. Actualizaciones autom\u0026aacute;ticas. BitLocker: cifrado de disco.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eCopias de seguridad\u003c/td\u003e\u003ctd\u003eTipos: completa, incremental, diferencial. Estrategia 3-2-1 (3 copias, 2 medios, 1 fuera del sitio). Herramientas: Historial de archivos Windows, Veeam Free, EaseUS Todo Backup. Verificaci\u0026oacute;n de integridad.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:12px\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:30%\"\u003eTema (Bloque B)\u003c/th\u003e\n                      \u003cth\u003eContenidos a estudiar\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eTipos de documentos de seguridad\u003c/td\u003e\u003ctd\u003ePol\u0026iacute;tica de seguridad: estructura y prop\u0026oacute;sito. Procedimiento t\u0026eacute;cnico: paso a paso de una actividad. Instructivo: gu\u0026iacute;a operativa de una herramienta. Registro: evidencia de que algo se realiz\u0026oacute;.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eInventario de activos con enfoque de seguridad\u003c/td\u003e\u003ctd\u003eClasificaci\u0026oacute;n: hardware, software, datos, personas. Valoraci\u0026oacute;n: criterios de criticidad (Alto/Medio/Bajo). Tabla de inventario con campo de nivel de riesgo.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eProtocolos de gesti\u0026oacute;n de la informaci\u0026oacute;n\u003c/td\u003e\u003ctd\u003eProtocolo de acceso a informaci\u0026oacute;n sensible. Protocolo de eliminaci\u0026oacute;n segura de datos. Protocolo b\u0026aacute;sico de respuesta ante incidentes.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eOrganizaci\u0026oacute;n y versionado de documentos\u003c/td\u003e\u003ctd\u003eConvenci\u0026oacute;n de nombres para documentos de seguridad. Control de versiones: historial de cambios. Estructura de carpetas para documentaci\u0026oacute;n. Herramientas con permisos restringidos: OneDrive, Google Drive.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128218; Material de apoyo\u003c/div\u003e\n                \u003cp\u003eCisco Skills for All \u0026mdash; \u003cem\u003eIntroducci\u0026oacute;n a la Ciberseguridad\u003c/em\u003e (curso gratuito) e\n                INCIBE \u0026mdash; \u003cem\u003eGu\u0026iacute;a de ciberseguridad para PYMEs\u003c/em\u003e. Los enlaces est\u0026aacute;n en la secci\u0026oacute;n\n                de Referencias de esta gu\u0026iacute;a.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eRegistro de estudio del aprendiz\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Del Bloque A: explica con tus palabras la Triada CIA y da un ejemplo de cada principio en una MiPyme\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g4c_321_cia\" data-track placeholder=\"Confidencialidad, Integridad y Disponibilidad: qu\u0026eacute; significa cada una y un ejemplo aplicado (ej.: solo el contador accede a n\u0026oacute;mina).\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Del Bloque A: elige 3 tipos de ciberataque y describe c\u0026oacute;mo funcionan y c\u0026oacute;mo se previenen\u003c/span\u003e\n                  \u003ctextarea rows=\"6\" data-store=\"g4c_321_ataques\" data-track placeholder=\"Ej.: ransomware (cifra archivos, se previene con copias + antivirus), phishing (correo falso, se previene verificando remitente)...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Del Bloque A: \u0026iquest;qu\u0026eacute; protege la Ley 1273 de 2009 y qu\u0026eacute; aporta la ISO 27001 a una empresa?\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g4c_321_normativa\" data-track placeholder=\"Ley 1273: delitos inform\u0026aacute;ticos en Colombia (acceso abusivo, da\u0026ntilde;o inform\u0026aacute;tico...). ISO 27001: modelo de gesti\u0026oacute;n SGSI.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Del Bloque B: \u0026iquest;en qu\u0026eacute; se diferencian una pol\u0026iacute;tica, un procedimiento, un instructivo y un registro?\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g4c_321_documentos\" data-track placeholder=\"Define cada tipo de documento con una frase y un ejemplo de ciberseguridad.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Del Bloque B: \u0026iquest;c\u0026oacute;mo se valora la criticidad de un activo y c\u0026oacute;mo se versiona un documento de seguridad?\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g4c_321_activos\" data-track placeholder=\"Criticidad Alto/Medio/Bajo seg\u0026uacute;n impacto. Versionado: NombreDocumento_FICHA_v1.0_AAAAMMDD e historial de cambios.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Dudas que quedaron para resolver antes del mapa conceptual\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_321_dudas\" data-track placeholder=\"Anota preguntas concretas para aclarar con el instructor antes de construir el mapa.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"bloques321DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloques321\" class=\"btn-save-response\" onclick=\"actStd_save_bloques321()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_bloques321()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloques321\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.2.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eMapa conceptual integrador\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n diagn\u0026oacute;stica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e construir en equipo un mapa conceptual digital que integre los conceptos de ciberseguridad y documentaci\u0026oacute;n t\u0026eacute;cnica de los Bloques A y B. Entregable: \u003ccode\u003eMapaConceptual_RAP03_[Equipo]_v1.0.pdf\u003c/code\u003e.\u003c/p\u003e\n\n              \u003cdiv class=\"equipo-guia4c-block\" data-equipo-g4c-mount=\"mapa322\" style=\"margin:12px 0 18px;padding:14px 16px;border:1px solid #cfe0d3;border-left:5px solid #0b6b35;border-radius:10px;background:linear-gradient(180deg,#f1f9f3,#ffffff)\"\u003e\n                \u003cdiv style=\"display:flex;gap:10px;align-items:flex-start;margin-bottom:10px\"\u003e\n                  \u003cdiv style=\"font-size:1.5rem;line-height:1\"\u003e\u0026#128101;\u003c/div\u003e\n                  \u003cdiv\u003e\n                    \u003cdiv style=\"font-weight:700;color:#0b6b35\"\u003eEquipo para 3.2.2\u003c/div\u003e\n                    \u003cp class=\"intro-text\" style=\"margin:2px 0 0;font-size:.88rem\"\u003eEl mapa conceptual se elabora en equipo de m\u0026aacute;ximo 3 integrantes: t\u0026uacute; y hasta 2 compa\u0026ntilde;eros de tu ficha.\u003c/p\u003e\n                  \u003c/div\u003e\n                \u003c/div\u003e\n                \u003cdiv data-equipo-g4c-summary=\"mapa322\"\u003e\u003c/div\u003e\n                \u003cdiv data-equipo-g4c-config=\"mapa322\" style=\"display:none\"\u003e\n                  \u003cdiv style=\"margin:6px 0 6px;font-weight:600;font-size:.88rem;color:#1b5e20\"\u003eSelecciona hasta 2 compa\u0026ntilde;eros (tu nombre ya est\u0026aacute; incluido):\u003c/div\u003e\n                  \u003cdiv data-equipo-g4c-roster=\"mapa322\" style=\"display:flex;flex-direction:column;gap:6px;max-height:260px;overflow:auto;padding:8px 10px;border:1px solid #cfe0d3;border-radius:8px;background:#ffffff\"\u003e\u003c/div\u003e\n                  \u003cdiv data-equipo-g4c-hint=\"mapa322\" class=\"intro-text\" style=\"margin:8px 0 0;font-size:.82rem;color:#4b5563\"\u003eCargando roster de la ficha\u0026hellip;\u003c/div\u003e\n                  \u003cdiv style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:10px\"\u003e\n                    \u003cbutton type=\"button\" onclick=\"confirmarEquipoGuia4C('mapa322')\" class=\"btn-save-response\"\u003e\u0026#128101; Confirmar equipo de 3.2.2\u003c/button\u003e\n                    \u003cbutton type=\"button\" onclick=\"cancelarEquipoGuia4CConfig('mapa322')\" style=\"padding:8px 16px;border:1px solid #cfe0d3;background:#ffffff;color:#37474f;border-radius:6px;font-family:inherit;font-size:.88rem;cursor:pointer\"\u003eCancelar\u003c/button\u003e\n                  \u003c/div\u003e\n                \u003c/div\u003e\n              \u003c/div\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; REQUISITOS DEL MAPA CONCEPTUAL\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eA\u003c/td\u003e\u003ctd\u003eM\u0026iacute;nimo \u003cstrong\u003e20 conceptos\u003c/strong\u003e relacionados entre s\u0026iacute; con conectores y palabras de enlace.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eB\u003c/td\u003e\u003ctd\u003eMostrar la conexi\u0026oacute;n: tipos de ataques \u0026rarr; controles de seguridad \u0026rarr; documentaci\u0026oacute;n requerida.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eC\u003c/td\u003e\u003ctd\u003eReferenciar al menos una normativa (ISO 27001 o Ley 1273).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eD\u003c/td\u003e\u003ctd\u003eElaborarse en CmapTools, MindMeister o Canva y exportarse en PDF.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eE\u003c/td\u003e\u003ctd\u003eSustentarse oralmente en 10 minutos ante el instructor.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eCon tu equipo, elijan la herramienta: CmapTools (cmap.ihmc.us), MindMeister (mindmeister.com) o Canva \u0026gt; \u0026laquo;mapa conceptual\u0026raquo;.\u003c/li\u003e\n                  \u003cli\u003eAntes de dise\u0026ntilde;ar en digital, hagan a mano un borrador de 10 minutos: concepto central, ramas principales, jerarqu\u0026iacute;a.\u003c/li\u003e\n                  \u003cli\u003eConstruyan el mapa integrando ciberseguridad y documentaci\u0026oacute;n t\u0026eacute;cnica: amenazas, controles, normativa y documentaci\u0026oacute;n.\u003c/li\u003e\n                  \u003cli\u003eUsen palabras de enlace claras: \u0026laquo;genera\u0026raquo;, \u0026laquo;se mitiga con\u0026raquo;, \u0026laquo;requiere\u0026raquo;, \u0026laquo;se documenta en\u0026raquo;, \u0026laquo;protege contra\u0026raquo;.\u003c/li\u003e\n                  \u003cli\u003eExporten a PDF. Nombre: \u003cstrong\u003eMapaConceptual_RAP03_[Equipo]_v1.0.pdf\u003c/strong\u003e.\u003c/li\u003e\n                  \u003cli\u003eSustenten oralmente en 10 minutos ante el instructor.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eRegistro del aprendiz\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Concepto central elegido por el equipo\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g4c_322_central\" data-track placeholder=\"Ej.: Ciberseguridad para una MiPyme.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Ramas principales del mapa (m\u0026iacute;nimo 4)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_322_ramas\" data-track placeholder=\"Lista las ramas: ataques, controles, normativa, documentaci\u0026oacute;n...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Palabras de enlace m\u0026aacute;s usadas\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g4c_322_enlaces\" data-track placeholder=\"Ej.: \u0026laquo;se mitiga con\u0026raquo;, \u0026laquo;requiere\u0026raquo;, \u0026laquo;protege\u0026raquo;...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. \u0026iquest;C\u0026oacute;mo muestra tu mapa la conexi\u0026oacute;n ataques \u0026rarr; controles \u0026rarr; documentaci\u0026oacute;n? Da un ejemplo concreto\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_322_conexion\" data-track placeholder=\"Ej.: ransomware \u0026rarr; copia de seguridad 3-2-1 \u0026rarr; protocolo de backup documentado.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"mapa322DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarMapa322\" class=\"btn-save-response\" onclick=\"actStd_save_mapa322()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_mapa322()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusMapa322\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-mapa322\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.3 APROPIACIÓN ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 \u0026middot; Actividades de Apropiaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de apropiación:\u003c/strong\u003e pones en práctica lo aprendido. La mayoría de las evidencias que debes entregar salen de esta fase.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eAplicar los conocimientos en un equipo de c\u0026oacute;mputo real: diagnosticar su estado de\n        seguridad, implementar controles de \u003cem\u003ehardening\u003c/em\u003e y elaborar la documentaci\u0026oacute;n t\u0026eacute;cnica\n        profesional que respalda el trabajo.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-apropiacion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128218;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Apropiaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003e3 actividades \u0026middot; Diagn\u0026oacute;stico + hardening + documentaci\u0026oacute;n t\u0026eacute;cnica\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.3.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eDiagn\u0026oacute;stico del estado de seguridad del equipo\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n t\u0026eacute;cnica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e realizar un an\u0026aacute;lisis completo del estado de seguridad de tu equipo (f\u0026iacute;sico o m\u0026aacute;quina virtual Windows) y registrar todos los hallazgos en la Tabla de Diagn\u0026oacute;stico suministrada por el instructor.\u003c/p\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; EVIDENCIA \u0026mdash; Tipo: Conocimiento + Desempe\u0026ntilde;o\u003c/span\u003e\n                \u003cspan style=\"opacity:0.5\"\u003e|\u003c/span\u003e\n                \u003cspan\u003eInstrumento: Lista de Chequeo LC-01\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; diagnosticar?\u003c/th\u003e\n                      \u003cth\u003eHerramienta / Ruta\u003c/th\u003e\n                      \u003cth\u003eEvidencia\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003e1. Windows Defender: \u0026iquest;activo? \u0026iquest;actualizado? \u0026iquest;an\u0026aacute;lisis programado?\u003c/td\u003e\u003ctd\u003eWindows Security \u0026rarr; Protecci\u0026oacute;n contra virus y amenazas\u003c/td\u003e\u003ctd\u003eCaptura del estado de protecci\u0026oacute;n\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e2. Firewall de Windows en los 3 perfiles (Dominio, Privado, P\u0026uacute;blico)\u003c/td\u003e\u003ctd\u003ePanel de control \u0026rarr; Firewall de Windows\u003c/td\u003e\u003ctd\u003eCaptura de los 3 perfiles\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e3. Actualizaciones del sistema: \u0026iquest;al d\u0026iacute;a? \u0026iquest;cu\u0026aacute;ntas pendientes?\u003c/td\u003e\u003ctd\u003eConfiguraci\u0026oacute;n \u0026rarr; Windows Update \u0026rarr; Ver historial\u003c/td\u003e\u003ctd\u003eCaptura del historial\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e4. Cuentas de usuario: \u0026iquest;administrador con contrase\u0026ntilde;a robusta? \u0026iquest;cuentas innecesarias?\u003c/td\u003e\u003ctd\u003e\u003ckbd\u003eWin + R\u003c/kbd\u003e \u0026rarr; \u003ccode\u003elusrmgr.msc\u003c/code\u003e \u0026rarr; Usuarios\u003c/td\u003e\u003ctd\u003eCaptura de la lista de cuentas\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e5. Software instalado: \u0026iquest;sin licencia, desconocido o desactualizado?\u003c/td\u003e\u003ctd\u003eBelarc Advisor (belarc.com) \u0026mdash; reporte HTML\u003c/td\u003e\u003ctd\u003eReporte HTML + captura del resumen\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e6. Copias de seguridad: \u0026iquest;existe estrategia actual? \u0026iquest;cu\u0026aacute;ndo fue la \u0026uacute;ltima copia?\u003c/td\u003e\u003ctd\u003eConfiguraci\u0026oacute;n \u0026rarr; Copia de seguridad\u003c/td\u003e\u003ctd\u003eCaptura del estado actual\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128295; Herramientas de diagn\u0026oacute;stico\u003c/div\u003e\n                \u003cp\u003eWindows Security Center \u0026middot; Belarc Advisor (gratuito, belarc.com) \u0026middot; \u003ccode\u003esecpol.msc\u003c/code\u003e \u0026middot; \u003ccode\u003elusrmgr.msc\u003c/code\u003e \u0026middot; \u003ccode\u003eservices.msc\u003c/code\u003e\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones (sin saltarte pasos)\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eAbre la Tabla de Diagn\u0026oacute;stico suministrada por el instructor. Encabezado: nombre completo, ficha, equipo asignado, fecha.\u003c/li\u003e\n                  \u003cli\u003eDescarga e instala Belarc Advisor (belarc.com). Ejec\u0026uacute;talo y guarda el reporte HTML.\u003c/li\u003e\n                  \u003cli\u003ePara cada uno de los 6 aspectos, sigue la ruta indicada, revisa el estado y registra los datos exactos.\u003c/li\u003e\n                  \u003cli\u003eToma captura de cada aspecto. N\u0026oacute;mbralas en orden: \u003ccode\u003e01_Defender.png\u003c/code\u003e, \u003ccode\u003e02_Firewall.png\u003c/code\u003e, \u003ccode\u003e03_Actualizaciones.png\u003c/code\u003e, \u003ccode\u003e04_Cuentas.png\u003c/code\u003e, \u003ccode\u003e05_Belarc.png\u003c/code\u003e, \u003ccode\u003e06_Backup.png\u003c/code\u003e.\u003c/li\u003e\n                  \u003cli\u003ePara cada hallazgo, asigna nivel de riesgo: \u003cstrong\u003eALTO\u003c/strong\u003e (acci\u0026oacute;n inmediata), \u003cstrong\u003eMEDIO\u003c/strong\u003e (atenci\u0026oacute;n pr\u0026oacute;xima), \u003cstrong\u003eBAJO\u003c/strong\u003e (mejora opcional). Justifica en observaciones.\u003c/li\u003e\n                  \u003cli\u003eOrganiza el reporte de Belarc y las 6 capturas en una carpeta: \u003ccode\u003eDiagnostico_[TuNombre]_[Fecha]\u003c/code\u003e.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eResumen del diagn\u0026oacute;stico (registro del aprendiz)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Estado general de seguridad del equipo diagnosticado\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_331_estado\" data-track placeholder=\"Resume si el equipo est\u0026aacute; bien protegido, parcialmente o vulnerable, con datos del diagn\u0026oacute;stico.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Los 3 hallazgos m\u0026aacute;s cr\u0026iacute;ticos (con nivel de riesgo)\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g4c_331_hallazgos\" data-track placeholder=\"Ej.: Defender desactivado (ALTO), Firewall p\u0026uacute;blico apagado (ALTO), 18 actualizaciones pendientes (MEDIO).\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Controles que priorizar\u0026iacute;as y por qu\u0026eacute;\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g4c_331_prioridades\" data-track placeholder=\"Lista los controles que aplicar\u0026iacute;as primero y justifica seg\u0026uacute;n el impacto en la informaci\u0026oacute;n.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Conclusi\u0026oacute;n t\u0026eacute;cnica (m\u0026iacute;nimo 8 l\u0026iacute;neas)\u003c/span\u003e\n                  \u003ctextarea rows=\"8\" data-store=\"g4c_331_conclusion\" data-track placeholder=\"P\u0026aacute;rrafo final con tu lectura t\u0026eacute;cnica del estado del equipo.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"diagnostico331DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarDiagnostico331\" class=\"btn-save-response\" onclick=\"actStd_save_diagnostico331()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_diagnostico331()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusDiagnostico331\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-diagnostico331\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.3.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eImplementaci\u0026oacute;n de controles de hardening\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n t\u0026eacute;cnica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e con base en el diagn\u0026oacute;stico, aplicar los 7 controles de seguridad y documentar cada acci\u0026oacute;n con su evidencia.\u003c/p\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; EVIDENCIA \u0026mdash; Tipo: Desempe\u0026ntilde;o\u003c/span\u003e\n                \u003cspan style=\"opacity:0.5\"\u003e|\u003c/span\u003e\n                \u003cspan\u003eInstrumento: Lista de Chequeo LC-02\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:2rem;text-align:center\"\u003eN.\u0026deg;\u003c/th\u003e\n                      \u003cth\u003eControl a implementar\u003c/th\u003e\n                      \u003cth\u003eRuta / Herramienta\u003c/th\u003e\n                      \u003cth\u003eEvidencia\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e1\u003c/td\u003e\u003ctd\u003eActivar Windows Defender + an\u0026aacute;lisis semanal programado\u003c/td\u003e\u003ctd\u003eWindows Security \u0026rarr; Protecci\u0026oacute;n contra virus\u003c/td\u003e\u003ctd\u003eCaptura: config activa\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e2\u003c/td\u003e\u003ctd\u003eConfigurar Firewall en 3 perfiles (Dominio, Privado, P\u0026uacute;blico)\u003c/td\u003e\u003ctd\u003ePanel de control \u0026rarr; Firewall \u0026rarr; Configuraci\u0026oacute;n avanzada\u003c/td\u003e\u003ctd\u003eCaptura: estado perfiles\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e3\u003c/td\u003e\u003ctd\u003ePol\u0026iacute;tica de contrase\u0026ntilde;as: m\u0026iacute;nimo 8 caracteres, complejidad activada, caducidad 90 d\u0026iacute;as\u003c/td\u003e\u003ctd\u003e\u003ckbd\u003eWin + R\u003c/kbd\u003e \u0026rarr; \u003ccode\u003esecpol.msc\u003c/code\u003e \u0026rarr; Directiva de contrase\u0026ntilde;as\u003c/td\u003e\u003ctd\u003eCaptura: directiva configurada\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e4\u003c/td\u003e\u003ctd\u003eVerificar y asegurar cuentas de usuario; deshabilitar cuentas innecesarias\u003c/td\u003e\u003ctd\u003e\u003ckbd\u003eWin + R\u003c/kbd\u003e \u0026rarr; \u003ccode\u003elusrmgr.msc\u003c/code\u003e \u0026rarr; Usuarios\u003c/td\u003e\u003ctd\u003eCaptura: lista usuarios\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e5\u003c/td\u003e\u003ctd\u003eActivar SmartScreen para apps y descargas\u003c/td\u003e\u003ctd\u003eConfiguraci\u0026oacute;n \u0026rarr; Seguridad de Windows \u0026rarr; SmartScreen\u003c/td\u003e\u003ctd\u003eCaptura: SmartScreen activo\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e6\u003c/td\u003e\u003ctd\u003eConfigurar actualizaciones autom\u0026aacute;ticas de Windows\u003c/td\u003e\u003ctd\u003eConfiguraci\u0026oacute;n \u0026rarr; Windows Update \u0026rarr; Opciones avanzadas\u003c/td\u003e\u003ctd\u003eCaptura: config actualiz.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e7\u003c/td\u003e\u003ctd\u003eImplementar copia de seguridad de archivos cr\u0026iacute;ticos\u003c/td\u003e\u003ctd\u003eHistorial de archivos Windows o EaseUS Todo Backup Free\u003c/td\u003e\u003ctd\u003eCaptura: copia exitosa\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Si un control no aplica\u003c/div\u003e\n                \u003cp\u003eSi un control no puede aplicarse (ej.: \u003ccode\u003esecpol.msc\u003c/code\u003e no disponible en Windows Home), documenta el motivo t\u0026eacute;cnico y describe c\u0026oacute;mo se aplicar\u0026iacute;a en un equipo con Windows Pro. Eso tambi\u0026eacute;n demuestra competencia.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:14px\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eRevisa tu Tabla de Diagn\u0026oacute;stico (Act. 3.3.1). Empieza por los hallazgos \u003cstrong\u003eALTO\u003c/strong\u003e, luego \u003cstrong\u003eMEDIO\u003c/strong\u003e.\u003c/li\u003e\n                  \u003cli\u003ePara cada control: sigue la ruta, implementa el cambio y toma captura.\u003c/li\u003e\n                  \u003cli\u003eEn tu bit\u0026aacute;cora de cambios registra: (a) estado antes, (b) acci\u0026oacute;n, (c) estado despu\u0026eacute;s, (d) observaciones.\u003c/li\u003e\n                  \u003cli\u003eSi aparece un error, copia el mensaje, busca soluci\u0026oacute;n en learn.microsoft.com y registra error + soluci\u0026oacute;n.\u003c/li\u003e\n                  \u003cli\u003eNombra cada captura: \u003ccode\u003e01_Defender_configurado.png\u003c/code\u003e, \u003ccode\u003e02_Firewall_3perfiles.png\u003c/code\u003e, \u003ccode\u003e03_Politica_contras.png\u003c/code\u003e, \u003ccode\u003e04_Cuentas_aseguradas.png\u003c/code\u003e, \u003ccode\u003e05_SmartScreen.png\u003c/code\u003e, \u003ccode\u003e06_Actualizaciones.png\u003c/code\u003e, \u003ccode\u003e07_Backup_exitoso.png\u003c/code\u003e. Carpeta: \u003ccode\u003eHardening_[TuNombre]_[Fecha]\u003c/code\u003e.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128218; Material de apoyo\u003c/div\u003e\n                \u003cp\u003eINCIBE \u0026mdash; \u003cem\u003eGu\u0026iacute;a de hardening para empresas\u003c/em\u003e (enlace en Referencias).\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eBit\u0026aacute;cora de cambios (registro del aprendiz)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Orden en que aplicaste los 7 controles (seg\u0026uacute;n riesgo)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_332_orden\" data-track placeholder=\"Ej.: 1) Defender, 2) Firewall, 3) Backup, 4) Contrase\u0026ntilde;as, ...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Resumen de cambios aplicados (estado antes / acci\u0026oacute;n / estado despu\u0026eacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"8\" data-store=\"g4c_332_resumen\" data-track placeholder=\"Para cada control, describe el cambio.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Errores encontrados y soluci\u0026oacute;n aplicada (si aplica)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_332_errores\" data-track placeholder=\"Mensaje exacto + fuente consultada + soluci\u0026oacute;n.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Conclusi\u0026oacute;n comparativa (m\u0026iacute;nimo 10 l\u0026iacute;neas)\u003c/span\u003e\n                  \u003ctextarea rows=\"10\" data-store=\"g4c_332_conclusion\" data-track placeholder=\"\u0026iquest;Cu\u0026aacute;nto mejor\u0026oacute; la postura de seguridad? \u0026iquest;Qu\u0026eacute; controles tuvieron mayor impacto?\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"hardening332DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarHardening332\" class=\"btn-save-response\" onclick=\"actStd_save_hardening332()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_hardening332()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusHardening332\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-hardening332\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.3.3 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.3\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eElaboraci\u0026oacute;n de documentaci\u0026oacute;n t\u0026eacute;cnica (documentos A-D)\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n t\u0026eacute;cnica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e elaborar los 4 documentos t\u0026eacute;cnicos profesionales que respaldan el trabajo de seguridad, aplicando la convenci\u0026oacute;n de nombres y la estructura de carpetas.\u003c/p\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128278; Convenci\u0026oacute;n de nombres (obligatoria)\u003c/div\u003e\n                \u003cp\u003e\u003ccode\u003eNombreDocumento_FICHA_v1.0_AAAAMMDD\u003c/code\u003e\u003cbr\u003e\n                Ejemplo: \u003ccode\u003ePoliticaSeguridad_3441939_v1.0_20260315\u003c/code\u003e\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; EVIDENCIA \u0026mdash; Tipo: Producto\u003c/span\u003e\n                \u003cspan style=\"opacity:0.5\"\u003e|\u003c/span\u003e\n                \u003cspan\u003eInstrumento: Lista de Chequeo LC-03\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:2rem;text-align:center\"\u003eDoc.\u003c/th\u003e\n                      \u003cth\u003eDocumento\u003c/th\u003e\n                      \u003cth\u003eEstructura m\u0026iacute;nima\u003c/th\u003e\n                      \u003cth\u003eFormato / Extensi\u0026oacute;n\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eA\u003c/td\u003e\u003ctd\u003eInforme de diagn\u0026oacute;stico de seguridad\u003c/td\u003e\u003ctd\u003ePortada, resumen ejecutivo, hallazgos por categor\u0026iacute;a (tabla), nivel de riesgo, conclusiones y recomendaciones. Capturas de pantalla incluidas.\u003c/td\u003e\u003ctd\u003eWord/PDF \u0026mdash; m\u0026iacute;n. 4 p\u0026aacute;ginas\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eB\u003c/td\u003e\u003ctd\u003ePol\u0026iacute;tica b\u0026aacute;sica de seguridad inform\u0026aacute;tica para MiPyme\u003c/td\u003e\u003ctd\u003ePortada, objetivo, alcance, definiciones, responsabilidades, controles aplicables, sanciones, control de versiones.\u003c/td\u003e\u003ctd\u003eWord/PDF \u0026mdash; m\u0026iacute;n. 3 p\u0026aacute;ginas\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eC\u003c/td\u003e\u003ctd\u003eInventario de activos con valoraci\u0026oacute;n de riesgos\u003c/td\u003e\u003ctd\u003eTabla: ID, nombre, tipo (hardware/software/datos), propietario, criticidad (A/M/B), amenaza principal, control aplicado.\u003c/td\u003e\u003ctd\u003eExcel o tabla en Word\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eD\u003c/td\u003e\u003ctd\u003eProtocolo de copias de seguridad\u003c/td\u003e\u003ctd\u003eObjetivo, alcance, responsable, frecuencia, tipo de backup, medio de almacenamiento, verificaci\u0026oacute;n, cronograma.\u003c/td\u003e\u003ctd\u003eWord \u0026mdash; m\u0026iacute;n. 2 p\u0026aacute;ginas\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128193; Estructura de carpetas (se eval\u0026uacute;a en la r\u0026uacute;brica)\u003c/div\u003e\n                \u003cp\u003eOrganiza los documentos en: \u003ccode\u003e01_Diagnostico\u003c/code\u003e / \u003ccode\u003e02_Politica_Seguridad\u003c/code\u003e / \u003ccode\u003e03_Inventario_Activos\u003c/code\u003e / \u003ccode\u003e04_Protocolo_Backup\u003c/code\u003e / \u003ccode\u003e05_Evidencias\u003c/code\u003e.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eRegistro de la documentaci\u0026oacute;n (antes de entregar)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eA. Informe de diagn\u0026oacute;stico: \u0026iquest;cu\u0026aacute;l fue el hallazgo principal y qu\u0026eacute; recomendaci\u0026oacute;n haces?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_333_informe\" data-track placeholder=\"Resume el hallazgo m\u0026aacute;s importante del informe y la recomendaci\u0026oacute;n asociada.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eB. Pol\u0026iacute;tica de seguridad: \u0026iquest;qu\u0026eacute; 3 controles incluiste y a qui\u0026eacute;n aplican?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_333_politica\" data-track placeholder=\"Ej.: contrase\u0026ntilde;as robustas (todos los empleados), copias semanales (responsable de sistemas), no abrir adjuntos sospechosos.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eC. Inventario de activos: lista tus 3 activos m\u0026aacute;s cr\u0026iacute;ticos con su criticidad y amenaza principal\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_333_inventario\" data-track placeholder=\"Ej.: PC administrativa (A, ransomware), base de clientes (A, robo de datos), impresora (B, da\u0026ntilde;o f\u0026iacute;sico).\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eD. Protocolo de backup: \u0026iquest;qu\u0026eacute; estrategia definiste? (frecuencia, tipo, medios, verificaci\u0026oacute;n)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g4c_333_protocolo\" data-track placeholder=\"Ej.: copia incremental diaria + completa semanal, disco externo + nube, verificaci\u0026oacute;n mensual restaurando un archivo.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"documentos333DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarDocumentos333\" class=\"btn-save-response\" onclick=\"actStd_save_documentos333()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_documentos333()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusDocumentos333\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-documentos333\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.4 TRANSFERENCIA ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 \u0026middot; Actividades de Transferencia del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de transferencia:\u003c/strong\u003e aplicas todo lo aprendido a un caso real o a una actividad integradora. Suele ser la evidencia más importante de la guía.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eIntegrar todo el trabajo de la gu\u0026iacute;a en un Plan Integral de Ciberseguridad para\n        ElectroBoyc\u0026aacute; S.A.S. (u otra MiPyme asignada por el instructor) y sustentarlo oralmente.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-transferencia\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128640;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Transferencia\u003c/h3\u003e\n              \u003cp\u003e1 actividad integradora \u0026middot; Plan Integral + sustentaci\u0026oacute;n oral\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.4.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003ePlan Integral de Ciberseguridad para MiPyme + Sustentaci\u0026oacute;n oral\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e integrar diagn\u0026oacute;stico, controles, documentaci\u0026oacute;n y estrategia de copias en un Plan Integral formal, y sustentarlo ante el instructor.\u003c/p\u003e\n\n              \u003carticle class=\"story-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026#127970; Escenario \u0026mdash; ElectroBoyc\u0026aacute; S.A.S., Tunja\u003c/h3\u003e\n                \u003cp\u003eEl mismo caso de la reflexi\u0026oacute;n inicial. Tras el ataque de ransomware, la empresa te\n                contrata como t\u0026eacute;cnico de sistemas para evaluar su situaci\u0026oacute;n y elaborar un plan que\n                evite futuros incidentes. Tienes el diagn\u0026oacute;stico (Act. 3.3.1), los controles\n                implementados (Act. 3.3.2) y la documentaci\u0026oacute;n t\u0026eacute;cnica (Act. 3.3.3). Ahora\n                consol\u0026iacute;dalos en un Plan Integral y pres\u0026eacute;ntalo a la gerencia.\u003c/p\u003e\n              \u003c/article\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; EVIDENCIA \u0026mdash; Tipo: Producto + Sustentaci\u0026oacute;n Oral\u003c/span\u003e\n                \u003cspan style=\"opacity:0.5\"\u003e|\u003c/span\u003e\n                \u003cspan\u003eInstrumento: Lista de Chequeo LC-04\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:2rem;text-align:center\"\u003eSec.\u003c/th\u003e\n                      \u003cth\u003eSecci\u0026oacute;n del plan\u003c/th\u003e\n                      \u003cth\u003eContenido m\u0026iacute;nimo requerido\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e1\u003c/td\u003e\u003ctd\u003eResumen ejecutivo\u003c/td\u003e\u003ctd\u003eSituaci\u0026oacute;n actual, riesgos identificados, objetivos del plan. 1 p\u0026aacute;gina.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e2\u003c/td\u003e\u003ctd\u003eDiagn\u0026oacute;stico\u003c/td\u003e\u003ctd\u003eResultados del 3.3.1 con tabla resumen y gr\u0026aacute;fico de estado.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e3\u003c/td\u003e\u003ctd\u003eControles implementados\u003c/td\u003e\u003ctd\u003eTabla de los 7 controles con resultado (S\u0026Iacute;/NO) y observaciones.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e4\u003c/td\u003e\u003ctd\u003ePol\u0026iacute;tica de seguridad\u003c/td\u003e\u003ctd\u003eVersi\u0026oacute;n final del documento B (Act. 3.3.3).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e5\u003c/td\u003e\u003ctd\u003eEstrategia de copias de seguridad\u003c/td\u003e\u003ctd\u003eProtocolo D con cronograma de ejecuci\u0026oacute;n.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e6\u003c/td\u003e\u003ctd\u003eInventario de activos\u003c/td\u003e\u003ctd\u003eTabla completa con valoraci\u0026oacute;n de riesgos.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e7\u003c/td\u003e\u003ctd\u003eRecomendaciones adicionales\u003c/td\u003e\u003ctd\u003eM\u0026iacute;nimo 3 mejoras a mediano plazo con justificaci\u0026oacute;n t\u0026eacute;cnica.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Formato del Plan\u003c/div\u003e\n                \u003cp\u003ePDF \u0026mdash; m\u0026iacute;nimo \u003cstrong\u003e12 p\u0026aacute;ginas\u003c/strong\u003e \u0026mdash; Arial 11 \u0026mdash; interlineado 1.15.\n                Los documentos del 3.3.3 van integrados o adjuntos.\u003cbr\u003e\n                Nombre: \u003ccode\u003ePlanCiberseguridad_NombreAprendiz_FICHA_v1.0_FECHA.pdf\u003c/code\u003e\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eSustentaci\u0026oacute;n oral del Plan de Ciberseguridad\u003c/h3\u003e\n                \u003cp class=\"intro-text\" style=\"margin:0 0 8px\"\u003ePrepara una presentaci\u0026oacute;n de \u003cstrong\u003e10 a 15 minutos\u003c/strong\u003e. El instructor realizar\u0026aacute; preguntas durante 5 minutos adicionales. M\u0026aacute;ximo 10 diapositivas:\u003c/p\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003e\u003cstrong\u003eDiapositiva 1:\u003c/strong\u003e Portada con nombre, ficha y fecha.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDiapositivas 2-3:\u003c/strong\u003e Diagn\u0026oacute;stico \u0026mdash; hallazgos cr\u0026iacute;ticos visualizados (gr\u0026aacute;fico o tabla).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDiapositivas 4-5:\u003c/strong\u003e Controles implementados \u0026mdash; antes y despu\u0026eacute;s.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDiapositiva 6:\u003c/strong\u003e Pol\u0026iacute;tica de seguridad \u0026mdash; puntos clave para la MiPyme.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDiapositiva 7:\u003c/strong\u003e Estrategia de backup \u0026mdash; esquema visual de la estrategia 3-2-1.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDiapositiva 8:\u003c/strong\u003e Recomendaciones a mediano plazo con justificaci\u0026oacute;n.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDiapositiva 9:\u003c/strong\u003e Lecciones aprendidas \u0026mdash; reflexi\u0026oacute;n personal.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026Iacute;ndice del Plan Integral (borrador previo a la redacci\u0026oacute;n)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Resumen ejecutivo (qu\u0026eacute; incluir\u0026aacute;s en una frase)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g4c_341_sec_resumen\" data-track placeholder=\"Situaci\u0026oacute;n actual, riesgos identificados, objetivos del plan.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Diagn\u0026oacute;stico (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g4c_341_sec_diagnostico\" data-track placeholder=\"Tabla resumen y gr\u0026aacute;fico de estado de la Act. 3.3.1.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Controles implementados (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g4c_341_sec_controles\" data-track placeholder=\"Tabla de los 7 controles con S\u0026Iacute;/NO y observaciones.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Pol\u0026iacute;tica de seguridad (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g4c_341_sec_politica\" data-track placeholder=\"Versi\u0026oacute;n final del documento B con sus controles.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Estrategia de copias de seguridad (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g4c_341_sec_backup\" data-track placeholder=\"Protocolo D con cronograma de ejecuci\u0026oacute;n y esquema 3-2-1.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Inventario de activos (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g4c_341_sec_inventario\" data-track placeholder=\"Tabla completa con valoraci\u0026oacute;n de riesgos del documento C.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e7. Recomendaciones adicionales (m\u0026iacute;nimo 3 con justificaci\u0026oacute;n t\u0026eacute;cnica)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g4c_341_sec_recomendaciones\" data-track placeholder=\"3 mejoras a mediano plazo: MFA, cifrado BitLocker, capacitaci\u0026oacute;n anti-phishing...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"plan341DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlan341\" class=\"btn-save-response\" onclick=\"actStd_save_plan341()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plan341()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlan341\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-plan341\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ EVIDENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003ePlanteamiento de Evidencias para la Evaluaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eResumen de lo que debes entregar:\u003c/strong\u003e usa esta sección como lista de chequeo final. Revisa que no te falte ninguna evidencia y cómo se evalúa cada una.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--entrega\"\u003e\u003cdiv class=\"gnote__label\"\u003e📦 Antes de entregar, revisa\u003c/div\u003e\n        \u003cul\u003e\n          \u003cli\u003eRespondiste todas las actividades que se piden como evidencia.\u003c/li\u003e\n          \u003cli\u003eTus archivos siguen la convenci\u0026oacute;n de nombres con tu ficha y la fecha.\u003c/li\u003e\n          \u003cli\u003eSubiste cada evidencia con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e y la ves marcada como \u003cstrong\u003eEntregada\u003c/strong\u003e en tu control de avance.\u003c/li\u003e\n        \u003c/ul\u003e\u003c/div\u003e\n\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128202;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eTabla de Evidencias del Proceso Formativo\u003c/h3\u003e\n              \u003cp\u003e4 evidencias con listas de chequeo LC-01 a LC-04\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\n                  \u003cth\u003eActividad de Aprendizaje\u003c/th\u003e\n                  \u003cth\u003eEvidencias\u003c/th\u003e\n                  \u003cth\u003eCriterios de Evaluaci\u0026oacute;n\u003c/th\u003e\n                  \u003cth\u003eT\u0026eacute;cnica e Instrumento\u003c/th\u003e\n                \u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.3.1 \u0026mdash; Diagn\u0026oacute;stico del estado de seguridad del equipo\u003c/td\u003e\n                  \u003ctd\u003eTabla de diagn\u0026oacute;stico completada + capturas de pantalla por categor\u0026iacute;a.\u003c/td\u003e\n                  \u003ctd\u003eAplica controles de seguridad seg\u0026uacute;n normativa, necesidades y restricciones de acceso a la informaci\u0026oacute;n (a partir del diagn\u0026oacute;stico del estado de protecci\u0026oacute;n).\u003c/td\u003e\n                  \u003ctd\u003eValoraci\u0026oacute;n de desempe\u0026ntilde;o (revisi\u0026oacute;n de evidencias y capturas). Lista de chequeo LC-01.\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.3.2 \u0026mdash; Implementaci\u0026oacute;n de controles de hardening (7 controles)\u003c/td\u003e\n                  \u003ctd\u003eEvidencias de configuraci\u0026oacute;n (capturas) + bit\u0026aacute;cora breve de cambios.\u003c/td\u003e\n                  \u003ctd\u003eAplica controles de seguridad seg\u0026uacute;n normativa, necesidades y restricciones de acceso a la informaci\u0026oacute;n.\u003c/td\u003e\n                  \u003ctd\u003eObservaci\u0026oacute;n directa y verificaci\u0026oacute;n pr\u0026aacute;ctica en el equipo. Lista de chequeo LC-02.\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.3.3 \u0026mdash; Elaboraci\u0026oacute;n de documentaci\u0026oacute;n t\u0026eacute;cnica (A-D)\u003c/td\u003e\n                  \u003ctd\u003eInforme de diagn\u0026oacute;stico, pol\u0026iacute;tica de seguridad, inventario de activos y protocolo de backup (seg\u0026uacute;n estructura m\u0026iacute;nima).\u003c/td\u003e\n                  \u003ctd\u003ePropone procesos de mejora en el manejo de la informaci\u0026oacute;n con base en la normativa vigente y gestiona las copias de seguridad y recuperaci\u0026oacute;n seg\u0026uacute;n los lineamientos establecidos.\u003c/td\u003e\n                  \u003ctd\u003eValoraci\u0026oacute;n de producto. Lista de chequeo LC-03.\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003eTransferencia \u0026mdash; Plan Integral de Ciberseguridad + sustentaci\u0026oacute;n oral\u003c/td\u003e\n                  \u003ctd\u003ePlan integral en PDF (m\u0026iacute;n. 12 p\u0026aacute;ginas) + presentaci\u0026oacute;n (10 diapositivas) y sustentaci\u0026oacute;n.\u003c/td\u003e\n                  \u003ctd\u003eAplica controles de seguridad, propone procesos de mejora y gestiona las copias de seguridad y recuperaci\u0026oacute;n seg\u0026uacute;n la normativa vigente y los lineamientos de la empresa.\u003c/td\u003e\n                  \u003ctd\u003eValoraci\u0026oacute;n de producto y sustentaci\u0026oacute;n oral. Lista de chequeo LC-04.\u003c/td\u003e\n                \u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ MATERIAL DE APOYO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"materiales\" class=\"section-title\"\u003eMaterial de Apoyo\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eDocumentos para descargar:\u003c/strong\u003e aquí está la normativa y las guías oficiales que necesitas para estudiar, elaborar los documentos técnicos y sustentar el Plan con fuentes reales.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#128230;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDocumentos oficiales de consulta\u003c/h3\u003e\n              \u003cp\u003e13 documentos en PDF \u0026middot; normativa, marcos de referencia y gu\u0026iacute;as t\u0026eacute;cnicas\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; C\u0026oacute;mo usar este material\u003c/div\u003e\n            \u003cp\u003eNo tienes que leerlo todo: la columna \u003cstrong\u003e\u0026laquo;\u0026Uacute;salo en\u0026raquo;\u003c/strong\u003e te dice en qu\u0026eacute;\n            actividad te sirve cada documento. Estos PDF tambi\u0026eacute;n son fuentes v\u0026aacute;lidas para la\n            bibliograf\u0026iacute;a del Plan Integral (Act. 3.4.1).\u003c/p\u003e\u003c/div\u003e\n\n          \u003cdiv class=\"table-scroll\" style=\"margin-top:14px\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\n                  \u003cth\u003eDocumento\u003c/th\u003e\n                  \u003cth style=\"width:24%\"\u003e\u0026Uacute;salo en\u003c/th\u003e\n                  \u003cth style=\"width:110px\"\u003eDescarga\u003c/th\u003e\n                \u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eNIST CSF 2.0 (en espa\u0026ntilde;ol)\u003c/strong\u003e \u0026mdash; Marco de Ciberseguridad: Identificar, Proteger, Detectar, Responder, Recuperar.\u003c/td\u003e\u003ctd\u003e3.2.1 \u0026middot; 3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/NIST_CSF_2_0_es.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eCONPES 3995 (2020)\u003c/strong\u003e \u0026mdash; Pol\u0026iacute;tica Nacional de Confianza y Seguridad Digital de Colombia.\u003c/td\u003e\u003ctd\u003e3.2.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/CONPES_3995_2020.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eEstrategia Nacional de Seguridad Digital 2025-2027\u003c/strong\u003e (MinTIC) \u0026mdash; contexto de pa\u0026iacute;s para la ciberseguridad.\u003c/td\u003e\u003ctd\u003e3.2.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/Estrategia_Nacional_Seguridad_Digital_Colombia_2025_2027.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eINCIBE \u0026mdash; Protecci\u0026oacute;n de la informaci\u0026oacute;n\u003c/strong\u003e \u0026mdash; gu\u0026iacute;a pr\u0026aacute;ctica de ciberseguridad para empresas peque\u0026ntilde;as.\u003c/td\u003e\u003ctd\u003e3.2.1 \u0026middot; 3.3.3 (doc. B)\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/INCIBE_Proteccion_de_la_informacion_mirror.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eINCIBE \u0026mdash; Copias de seguridad y borrado seguro: 12 consejos\u003c/strong\u003e.\u003c/td\u003e\u003ctd\u003e3.3.2 (control 7) \u0026middot; 3.3.3 (doc. D)\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/12_consejos_copias_borrado_seguro.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eMinTIC \u0026mdash; Gesti\u0026oacute;n y Clasificaci\u0026oacute;n de Activos de Informaci\u0026oacute;n (2016)\u003c/strong\u003e \u0026mdash; c\u0026oacute;mo inventariar y clasificar activos.\u003c/td\u003e\u003ctd\u003e3.3.3 (doc. C)\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/MinTIC_Guia_Gestion_Clasificacion_Activos_2016.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eMinTIC \u0026mdash; Lineamientos de Inventario y Clasificaci\u0026oacute;n de Activos (2025)\u003c/strong\u003e \u0026mdash; versi\u0026oacute;n actualizada de los lineamientos.\u003c/td\u003e\u003ctd\u003e3.3.3 (doc. C)\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/MinTIC_Lineamientos_Inventario_Clasificacion_Activos_2025.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eMinTIC G7 \u0026mdash; Gu\u0026iacute;a de Gesti\u0026oacute;n de Riesgos\u003c/strong\u003e \u0026mdash; c\u0026oacute;mo valorar probabilidad, impacto y criticidad.\u003c/td\u003e\u003ctd\u003e3.3.3 (doc. C) \u0026middot; 3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/MinTIC_Guia_Gestion_Riesgos_G7.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eMinTIC \u0026mdash; Lineamientos del Modelo de Gesti\u0026oacute;n de Riesgos de Seguridad (2025)\u003c/strong\u003e.\u003c/td\u003e\u003ctd\u003e3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/MinTIC_Lineamientos_Modelo_Gestion_Riesgo_SI_2025.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eMinTIC G21 \u0026mdash; Gesti\u0026oacute;n y Clasificaci\u0026oacute;n de Incidentes de Seguridad\u003c/strong\u003e \u0026mdash; base del protocolo de respuesta ante incidentes.\u003c/td\u003e\u003ctd\u003e3.2.1 \u0026middot; 3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/MinTIC_Guia_Gestion_Clasificacion_Incidentes_G21.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eMinTIC G9 \u0026mdash; Indicadores de Gesti\u0026oacute;n de Seguridad\u003c/strong\u003e \u0026mdash; c\u0026oacute;mo medir que los controles funcionan.\u003c/td\u003e\u003ctd\u003e3.4.1 (recomendaciones)\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/MinTIC_Guia_Indicadores_Gestion_Seguridad_G9.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eMinTIC G12 \u0026mdash; Seguridad en la Nube\u003c/strong\u003e \u0026mdash; criterios para usar la nube como medio de copia (estrategia 3-2-1).\u003c/td\u003e\u003ctd\u003e3.3.3 (doc. D) \u0026middot; 3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/MinTIC_Guia_Seguridad_en_la_Nube_G12.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003cstrong\u003eMinTIC \u0026mdash; Modelo de Seguridad y Privacidad de la Informaci\u0026oacute;n (MSPI)\u003c/strong\u003e \u0026mdash; modelo de referencia para la pol\u0026iacute;tica de seguridad.\u003c/td\u003e\u003ctd\u003e3.3.3 (doc. B) \u0026middot; 3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia4ciber/MinTIC_Modelo_Seguridad_Privacidad_Informacion_MSPI.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"info-box green\" style=\"margin-top:16px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128295; Herramientas para el diagn\u0026oacute;stico y el backup\u003c/div\u003e\n            \u003cp\u003eDesc\u0026aacute;rgalas siempre de la fuente oficial (buena pr\u0026aacute;ctica de ciberseguridad):\n            \u003ca href=\"https://www.belarc.com/products/belarc-advisor\" target=\"_blank\" rel=\"noopener\"\u003e\u003cstrong\u003eBelarc Advisor\u003c/strong\u003e\u003c/a\u003e\n            para el diagn\u0026oacute;stico (Act. 3.3.1) y\n            \u003ca href=\"https://www.easeus.com/backup-software/tb-free.html\" target=\"_blank\" rel=\"noopener\"\u003e\u003cstrong\u003eEaseUS Todo Backup Free\u003c/strong\u003e\u003c/a\u003e\n            o el Historial de archivos de Windows para la copia de seguridad (Act. 3.3.2, control 7).\n            Si el internet del aula falla, el instructor tiene los instaladores listos para compartir.\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ GLOSARIO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de T\u0026eacute;rminos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#fff3e0\"\u003e\u0026#128214;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eConceptos clave de ciberseguridad\u003c/h3\u003e\n              \u003cp\u003e19 t\u0026eacute;rminos t\u0026eacute;cnicos y normativos\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary-list\"\u003e\n            \u003cdt\u003eActivo de informaci\u0026oacute;n\u003c/dt\u003e\u003cdd\u003eCualquier dato, documento o recurso informacional (digital o f\u0026iacute;sico) que tiene valor para la organizaci\u0026oacute;n y debe protegerse.\u003c/dd\u003e\n            \u003cdt\u003eAmenaza\u003c/dt\u003e\u003cdd\u003eCausa potencial de un incidente no deseado que puede resultar en da\u0026ntilde;o a un sistema o activo de informaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eAn\u0026aacute;lisis de riesgos\u003c/dt\u003e\u003cdd\u003eProceso para identificar amenazas y vulnerabilidades, estimar su probabilidad/impacto y priorizar controles de mitigaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eBackup (copia de seguridad)\u003c/dt\u003e\u003cdd\u003eCopia de datos o sistemas para recuperaci\u0026oacute;n ante p\u0026eacute;rdida, corrupci\u0026oacute;n o incidente de seguridad; se recomienda automatizar y verificar.\u003c/dd\u003e\n            \u003cdt\u003eBitLocker\u003c/dt\u003e\u003cdd\u003eFuncionalidad de Windows para cifrado de unidad que protege datos frente a acceso no autorizado en caso de p\u0026eacute;rdida o robo del equipo.\u003c/dd\u003e\n            \u003cdt\u003eCiberseguridad\u003c/dt\u003e\u003cdd\u003eConjunto de pr\u0026aacute;cticas y controles para proteger sistemas, redes y datos ante riesgos y amenazas en el entorno digital.\u003c/dd\u003e\n            \u003cdt\u003eTriada CIA\u003c/dt\u003e\u003cdd\u003ePrincipios de seguridad de la informaci\u0026oacute;n: \u003cstrong\u003eConfidencialidad, Integridad y Disponibilidad\u003c/strong\u003e.\u003c/dd\u003e\n            \u003cdt\u003eControl de seguridad\u003c/dt\u003e\u003cdd\u003eMedida preventiva, detectiva o correctiva destinada a reducir riesgos y mejorar la protecci\u0026oacute;n de activos.\u003c/dd\u003e\n            \u003cdt\u003eFirewall\u003c/dt\u003e\u003cdd\u003eComponente que filtra tr\u0026aacute;fico de red seg\u0026uacute;n reglas, permitiendo o bloqueando conexiones para reducir exposici\u0026oacute;n a ataques.\u003c/dd\u003e\n            \u003cdt\u003eHardening (endurecimiento)\u003c/dt\u003e\u003cdd\u003eProceso de configuraci\u0026oacute;n segura de un sistema para reducir vulnerabilidades (actualizaciones, pol\u0026iacute;ticas, desactivar servicios innecesarios, etc.).\u003c/dd\u003e\n            \u003cdt\u003eIncidente de seguridad\u003c/dt\u003e\u003cdd\u003eEvento que compromete o amenaza la confidencialidad, integridad o disponibilidad de la informaci\u0026oacute;n o de los sistemas.\u003c/dd\u003e\n            \u003cdt\u003eIngenier\u0026iacute;a social\u003c/dt\u003e\u003cdd\u003eT\u0026eacute;cnicas de manipulaci\u0026oacute;n para inducir a personas a revelar informaci\u0026oacute;n, ejecutar acciones o vulnerar controles.\u003c/dd\u003e\n            \u003cdt\u003eMalware\u003c/dt\u003e\u003cdd\u003eSoftware malicioso dise\u0026ntilde;ado para da\u0026ntilde;ar, interrumpir u obtener acceso no autorizado a sistemas o datos.\u003c/dd\u003e\n            \u003cdt\u003ePhishing\u003c/dt\u003e\u003cdd\u003eModalidad de fraude que busca enga\u0026ntilde;ar para obtener credenciales o informaci\u0026oacute;n sensible mediante mensajes o sitios falsos.\u003c/dd\u003e\n            \u003cdt\u003ePol\u0026iacute;tica de seguridad\u003c/dt\u003e\u003cdd\u003eDocumento que define reglas, responsabilidades y controles m\u0026iacute;nimos para proteger informaci\u0026oacute;n y sistemas en una organizaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eRansomware\u003c/dt\u003e\u003cdd\u003eTipo de malware que cifra archivos o bloquea sistemas y exige pago para recuperar el acceso.\u003c/dd\u003e\n            \u003cdt\u003eSGSI\u003c/dt\u003e\u003cdd\u003eSistema de Gesti\u0026oacute;n de Seguridad de la Informaci\u0026oacute;n; modelo de gesti\u0026oacute;n para establecer, implementar, mantener y mejorar la seguridad de la informaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eSmartScreen\u003c/dt\u003e\u003cdd\u003eFunci\u0026oacute;n de Windows que ayuda a proteger contra descargas y aplicaciones potencialmente maliciosas.\u003c/dd\u003e\n            \u003cdt\u003eVulnerabilidad\u003c/dt\u003e\u003cdd\u003eDebilidad que puede ser explotada por una amenaza para afectar un activo o sistema.\u003c/dd\u003e\n          \u003c/dl\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ REFERENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes Bibliogr\u0026aacute;ficos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#ede7f6\"\u003e\u0026#128279;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eFuentes oficiales y normativas\u003c/h3\u003e\n              \u003cp\u003e11 referencias t\u0026eacute;cnicas y normativas para consulta\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003col class=\"references-list\" style=\"padding-left:1.4rem;line-height:1.8\"\u003e\n            \u003cli\u003eISO. (2022). \u003cem\u003eISO/IEC 27001:2022 \u0026mdash; Information security management systems \u0026mdash; Requirements\u003c/em\u003e. \u003ca href=\"https://www.iso.org/standard/27001\" target=\"_blank\" rel=\"noopener\"\u003eiso.org/standard/27001\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eNIST. (2024). \u003cem\u003eEl Marco de Seguridad Cibern\u0026eacute;tica (CSF) 2.0 del NIST\u003c/em\u003e. NIST CSWP 29. \u003ca href=\"https://nvlpubs.nist.gov/nistpubs/CSWP/NIST.CSWP.29.spa.pdf\" target=\"_blank\" rel=\"noopener\"\u003envlpubs.nist.gov\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eDNP. (2020). \u003cem\u003eDocumento CONPES 3995: Pol\u0026iacute;tica Nacional de Confianza y Seguridad Digital\u003c/em\u003e. \u003ca href=\"https://colaboracion.dnp.gov.co/cdt/Conpes/Econ%C3%B3micos/3995.pdf\" target=\"_blank\" rel=\"noopener\"\u003ecolaboracion.dnp.gov.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eCongreso de Colombia. (2009). \u003cem\u003eLey 1273 de 2009 \u0026mdash; Delitos inform\u0026aacute;ticos\u003c/em\u003e. Diario Oficial No. 47.223. \u003ca href=\"https://www.secretariasenado.gov.co/senado/basedoc/ley_1273_2009.html\" target=\"_blank\" rel=\"noopener\"\u003esecretariasenado.gov.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMinTIC. (2025). \u003cem\u003eEstrategia Nacional de Seguridad Digital de Colombia\u003c/em\u003e. \u003ca href=\"https://www.mintic.gov.co/portal/715/articles-403023_recurso_2.pdf\" target=\"_blank\" rel=\"noopener\"\u003emintic.gov.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMinTIC. (2016). \u003cem\u003eGu\u0026iacute;a para la Gesti\u0026oacute;n y Clasificaci\u0026oacute;n de Activos de Informaci\u0026oacute;n\u003c/em\u003e. \u003ca href=\"https://gobiernodigital.mintic.gov.co/692/articles-5482_G5_Gestion_Clasificacion.pdf\" target=\"_blank\" rel=\"noopener\"\u003egobiernodigital.mintic.gov.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMicrosoft. (2025). \u003cem\u003eProgramar an\u0026aacute;lisis peri\u0026oacute;dicos con Microsoft Defender\u003c/em\u003e. \u003ca href=\"https://learn.microsoft.com/en-us/defender-endpoint/schedule-antivirus-scans\" target=\"_blank\" rel=\"noopener\"\u003elearn.microsoft.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eVeeam. (2025). \u003cem\u003eVeeam Agent for Microsoft Windows \u0026mdash; Backup\u003c/em\u003e. \u003ca href=\"https://helpcenter.veeam.com/docs/agentforwindows/userguide/backup.html\" target=\"_blank\" rel=\"noopener\"\u003ehelpcenter.veeam.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eINCIBE. \u003cem\u003ePol\u0026iacute;ticas de seguridad para la pyme\u003c/em\u003e. \u003ca href=\"https://www.incibe.es/empresas/herramientas/politicas\" target=\"_blank\" rel=\"noopener\"\u003eincibe.es/empresas/herramientas/politicas\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eCisco Skills for All. \u003cem\u003eIntroducci\u0026oacute;n a Ciberseguridad\u003c/em\u003e. \u003ca href=\"https://skillsforall.examscisco.com/producto/introduccion-a-ciberseguridad/\" target=\"_blank\" rel=\"noopener\"\u003eskillsforall.examscisco.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eBelarc. \u003cem\u003eBelarc Advisor \u0026mdash; Inventario de sistema\u003c/em\u003e. \u003ca href=\"https://www.belarc.com/products/belarc-advisor\" target=\"_blank\" rel=\"noopener\"\u003ebelarc.com/products/belarc-advisor\u003c/a\u003e\u003c/li\u003e\n          \u003c/ol\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
